# Habit history stays in memory until the user saves a JSON file.
import datetime
import json
import os
import tempfile
from pathlib import Path


def habit_streak(days, today=None):
    # Yesterday's streak remains visible until today's habit is completed.
    today = today or datetime.date.today()
    recorded = set(days)
    cursor = today if today.isoformat() in recorded else today - datetime.timedelta(days=1)
    streak = 0
    while cursor.isoformat() in recorded:
        streak += 1
        cursor -= datetime.timedelta(days=1)
    return streak


def habit_render(app):
    app.HabitList.delete(0, "end")
    today = datetime.date.today().isoformat()
    for habit in app.habits:
        mark = "[done]" if today in habit["days"] else "[ ]"
        app.HabitList.insert("end", f"{mark} {habit['name']} | streak: {habit_streak(habit['days'])} | total: {len(habit['days'])}")
    app.StatusLabel.configure(text=f"{len(app.habits)} habits | Today: {today} | Save manually to keep changes")


def habit_add(app):
    # Names are short, nonempty and unique ignoring letter case.
    name = app.HabitEntry.get().strip()
    if not name or len(name) > 80 or len(app.habits) >= 200 or any(h["name"].casefold() == name.casefold() for h in app.habits):
        messagebox.showerror("Habit", "Use a unique name of 1-80 characters (maximum 200 habits).")
        return
    app.habits.append({"name": name, "days": []})
    app.HabitEntry.delete(0, "end")
    habit_render(app)


def habit_toggle(app):
    selected = app.HabitList.curselection()
    if not selected:
        return
    habit = app.habits[selected[0]]
    today = datetime.date.today().isoformat()
    if today in habit["days"]:
        habit["days"].remove(today)
    else:
        habit["days"].append(today)
        habit["days"].sort()
    habit_render(app)
    app.HabitList.selection_set(selected[0])


def habit_remove(app):
    selected = app.HabitList.curselection()
    if selected and messagebox.askyesno("Remove habit", "Remove the selected habit and its history?", parent=app.Form1):
        del app.habits[selected[0]]
        habit_render(app)


def habit_validate(data):
    # Validate the entire file before replacing the current collection.
    if not isinstance(data, list) or len(data) > 200:
        raise ValueError("Expected a list of up to 200 habits.")
    result, names = [], set()
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Invalid habit record.")
        name, days = item.get("name"), item.get("days")
        if not isinstance(name, str) or not name.strip() or len(name) > 80 or name.casefold() in names:
            raise ValueError("Invalid or duplicate habit name.")
        if not isinstance(days, list) or len(days) > 3660 or not all(isinstance(day, str) for day in days):
            raise ValueError("Invalid day history.")
        for day in days:
            if datetime.date.fromisoformat(day).isoformat() != day:
                raise ValueError("Dates must use YYYY-MM-DD.")
        names.add(name.casefold())
        result.append({"name": name, "days": sorted(set(days))})
    return result


def habit_save(app):
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".json", filetypes=[("Habit JSON", "*.json")])
    if not filename:
        return
    temporary = None
    try:
        path = Path(filename)
        content = json.dumps(habit_validate(app.habits), ensure_ascii=False, indent=2)
        descriptor, temporary = tempfile.mkstemp(dir=path.parent, prefix=".habit-", suffix=".tmp")
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        app.StatusLabel.configure(text="Habit history saved")
    except (OSError, ValueError) as error:
        messagebox.showerror("Save habits", str(error), parent=app.Form1)
    finally:
        if temporary is not None:
            Path(temporary).unlink(missing_ok=True)


def habit_open(app):
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Habit JSON", "*.json")])
    if not filename:
        return
    try:
        path = Path(filename)
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("File exceeds 2 MiB.")
        data = habit_validate(json.loads(path.read_text(encoding="utf-8-sig")))
    except (OSError, ValueError, UnicodeError) as error:
        messagebox.showerror("Open habits", str(error), parent=app.Form1)
        return
    if messagebox.askyesno("Open habits", "Replace the current collection? Save it first if needed.", parent=app.Form1):
        app.habits = data
        habit_render(app)


def habit_close(app):
    # Saving is explicit; always confirm before closing a collection.
    if messagebox.askyesno("Close tracker", "Close without saving? Use Save first to keep changes.", parent=app.Form1):
        app.root.destroy()
